 * Cell address handling: parsing an address word into column/row numbers,
 * ordering addresses, and formatting them back to canonical text.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Converts a 1-2 letter column string to its 1-based numeric index (A=1, Z=26, AA=27, ZZ=702). */
export function colLettersToNum(letters) {
  let n = 0
  for (const ch of letters.toUpperCase()) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/** Converts a 1-based numeric column index back to its letters (inverse of colLettersToNum). */
export function numToColLetters(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parses a bare word (already upper-cased or not) as a candidate cell address.
 * Returns { valid, col, row, key } where col/row are only meaningful when
 * valid is true. `key` is the canonical "COLROW" string used to index cells.
 */
export function parseAddress(word) {
  const upper = word.toUpperCase()
  const m = ADDRESS_RE.exec(upper)
  if (!m) return { valid: false }
  const letters = m[1]
  const row = parseInt(m[2], 10)
  if (row < 1) return { valid: false }
  const col = colLettersToNum(letters)
  if (col > 702) return { valid: false }
  return { valid: true, col, row, key: `${letters}${row}` }
}

/** Builds the canonical key/text for a column/row pair. */
export function addressText(col, row) {
  return `${numToColLetters(col)}${row}`
}

/** Compares two {col,row} addresses by ascending column then ascending row. */
export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

