{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-ltMwmW/src/parseSheet.js","content":"import { parseAddress } from './address.js'
import { SheetError } from './sheetError.js'

/**
 * Parses the sheet text (as read from standard input) into a Map from
 * canonical address key to { content, col, row }. Throws SheetError on the
 * first invalid address or duplicate declaration, per the CLI's contract.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const m = /^([^ \t]+)([ \t]?)(.*)$/s.exec(stripped)
    const addressWord = m[1]
    const hadSep = m[2] !== ''
    const rest = hadSep ? m[3] : ''

    const parsed = parseAddress(addressWord)
    if (!parsed.valid) {
      throw new SheetError(`error: line ${lineNo}: invalid cell address ${addressWord}`)
    }
    if (cells.has(parsed.key)) {
      throw new SheetError(`error: line ${lineNo}: cell ${parsed.key} is declared twice`)
    }
    cells.set(parsed.key, { content: rest, col: parsed.col, row: parsed.row })
  }
  return cells
}
"}

