{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-ltMwmW/src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text following the leading `=`).
 * Throws a plain Error on any character the grammar does not accept; the
 * caller treats any thrown error as a grammar failure (#ERR!).
 */

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (/[0-9]/.test(ch)) {
      let j = i + 1
      while (j < n && /[0-9]/.test(src[j])) j++
      if (src[j] === '.' && /[0-9]/.test(src[j + 1] ?? '')) {
        j++
        while (j < n && /[0-9]/.test(src[j])) j++
      }
      tokens.push({ type: 'NUMBER', value: src.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < n && /[A-Za-z0-9]/.test(src[j])) j++
      tokens.push({ type: 'WORD', value: src.slice(i, j) })
      i = j
      continue
    }
    if (ch === '<') {
      if (src[i + 1] === '=') {
        tokens.push({ type: 'OP', value: '<=' })
        i += 2
      } else if (src[i + 1] === '>') {
        tokens.push({ type: 'OP', value: '<>' })
        i += 2
      } else {
        tokens.push({ type: 'OP', value: '<' })
        i += 1
      }
      continue
    }
    if (ch === '>') {
      if (src[i + 1] === '=') {
        tokens.push({ type: 'OP', value: '>=' })
        i += 2
      } else {
        tokens.push({ type: 'OP', value: '>' })
        i += 1
      }
      continue
    }
    if ('^*/+-='.includes(ch)) {
      tokens.push({ type: 'OP', value: ch })
      i++
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'LPAREN' })
      i++
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'RPAREN' })
      i++
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    throw new Error(`unexpected character ${ch}`)
  }
  return tokens
}
"}

