export const numberValue = (n) => ({ kind: 'number', n })
export const textValue = (s) => ({ kind: 'text', s })
export const boolValue = (b) => ({ kind: 'bool', b })
export const errorValue = (e) => ({ kind: 'error', e })

export const isError = (v) => v.kind === 'error'

/** Reads a value as a number in an arithmetic position: booleans become 1/0, text is #VALUE!. */
export function coerceNumber(v) {
  if (v.kind === 'number') return v
  if (v.kind === 'bool') return numberValue(v.b ? 1 : 0)
  if (v.kind === 'text') return errorValue('#VALUE!')
  return v
}

/** Wraps a raw arithmetic result, turning non-finite results into #DIV/0!. */
export function finiteOrDivZero(n) {
  return Number.isFinite(n) ? numberValue(n) : errorValue('#DIV/0!')
}

const RANK = { number: 0, text: 1, bool: 2 }

/** Total order used by comparisons: number < text < bool, each ordered internally as specified. */
export function compareValues(a, b) {
  const ra = RANK[a.kind]
  const rb = RANK[b.kind]
  if (ra !== rb) return ra - rb
  if (a.kind === 'number') return a.n - b.n
  if (a.kind === 'text') return a.s < b.s ? -1 : a.s > b.s ? 1 : 0
  return (a.b ? 1 : 0) - (b.b ? 1 : 0)
}
"}

