/**
 * Expands a range AST node ({from, to} address words) into the ordered list
 * of {key} cells it covers, ascending column then ascending row. Returns
 * null when either corner is not a valid address.
 */
export function expandRange(node) {
  const p1 = parseAddress(node.from)
  const p2 = parseAddress(node.to)
  if (!p1.valid || !p2.valid) return null
  const colMin = Math.min(p1.col, p2.col)
  const colMax = Math.max(p1.col, p2.col)
  const rowMin = Math.min(p1.row, p2.row)
  const rowMax = Math.max(p1.row, p2.row)
  const cells = []
  for (let col = colMin; col <= colMax; col++) {
    for (let row = rowMin; row <= rowMax; row++) {
      cells.push({ col, row, key: addressText(col, row) })
    }
  }
  return cells
}
"}

