{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-ltMwmW/src/engine.js","content":"import { parseAddress } from './address.js'
import { parseFormula } from './parser.js'
import { parseLiteral } from './literal.js'
import { expandRange } from './range.js'
import { numberValue, boolValue, errorValue, isError, coerceNumber, finiteOrDivZero, compareValues } from './value.js'

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const AGGREGATE_FNS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

/**
 * Evaluates every declared cell's Value, memoizing results and detecting
 * cycles: a cell reached while it is itself still being evaluated is
 * #CYCLE! for that reference.
 */
export class Engine {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.visiting = new Set()
    this.astCache = new Map()
  }

  /** Parses a cell's formula body once and caches the AST (or the failure). */
  getAst(key, content) {
    if (this.astCache.has(key)) return this.astCache.get(key)
    let ast
    try {
      ast = parseFormula(content.slice(1))
    } catch {
      ast = null
    }
    this.astCache.set(key, ast)
    return ast
  }

  getCellValue(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    if (this.visiting.has(key)) return errorValue('#CYCLE!')
    this.visiting.add(key)
    const value = this.computeCellValue(key)
    this.visiting.delete(key)
    this.memo.set(key, value)
    return value
  }

  computeCellValue(key) {
    const cell = this.cells.get(key)
    if (!cell) return numberValue(0)
    const content = cell.content
    if (content.startsWith('=')) {
      const ast = this.getAst(key, content)
      if (!ast) return errorValue('#ERR!')
      return this.evalAst(ast)
    }
    return parseLiteral(content)
  }

  resolveAddress(word) {
    const p = parseAddress(word)
    if (!p.valid) return errorValue('#REF!')
    return this.getCellValue(p.key)
  }

  evalAst(node) {
    switch (node.type) {
      case 'num':
        return numberValue(node.value)
      case 'bool':
        return boolValue(node.value)
      case 'addr':
        return this.resolveAddress(node.word)
      case 'unary':
        return this.evalUnary(node)
      case 'bin':
        return this.evalBin(node)
      case 'call':
        return this.evalCall(node)
      case 'range':
        // A range can only appear here if it slipped in as a whole
        // non-call expression, which the grammar does not accept.
        return errorValue('#ERR!')
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  evalUnary(node) {
    const v = this.evalAst(node.operand)
    if (isError(v)) return v
    const c = coerceNumber(v)
    if (isError(c)) return c
    return finiteOrDivZero(node.op === '-' ? -c.n : c.n)
  }

  evalBin(node) {
    const left = this.evalAst(node.left)
    if (isError(left)) return left
    const right = this.evalAst(node.right)
    if (isError(right)) return right
    if (COMPARE_OPS.has(node.op)) return this.applyCompare(node.op, left, right)
    return this.applyArith(node.op, left, right)
  }

  applyCompare(op, left, right) {
    const cmp = compareValues(left, right)
    switch (op) {
      case '=':
        return boolValue(cmp === 0)
      case '<>':
        return boolValue(cmp !== 0)
      case '<':
        return boolValue(cmp < 0)
      case '<=':
        return boolValue(cmp <= 0)
      case '>':
        return boolValue(cmp > 0)
      case '>=':
        return boolValue(cmp >= 0)
      default:
        throw new Error(`unknown comparison ${op}`)
    }
  }

  applyArith(op, left, right) {
    const lc = coerceNumber(left)
    if (isError(lc)) return lc
    const rc = coerceNumber(right)
    if (isError(rc)) return rc
    switch (op) {
      case '+':
        return finiteOrDivZero(lc.n + rc.n)
      case '-':
        return finiteOrDivZero(lc.n - rc.n)
      case '*':
        return finiteOrDivZero(lc.n * rc.n)
      case '/':
        if (rc.n === 0) return errorValue('#DIV/0!')
        return finiteOrDivZero(lc.n / rc.n)
      case '^':
        return finiteOrDivZero(Math.pow(lc.n, rc.n))
      default:
        throw new Error(`unknown operator ${op}`)
    }
  }

  /** Evaluates one function argument to its list of contributed values (ranges expand). */
  evalArgValues(node) {
    if (node.type === 'range') {
      const cells = expandRange(node)
      if (!cells) return [errorValue('#REF!')]
      return cells.map((c) => this.getCellValue(c.key))
    }
    return [this.evalAst(node)]
  }

  flattenArgs(args) {
    const values = []
    for (const arg of args) values.push(...this.evalArgValues(arg))
    return values
  }

  /** Evaluates a single-value argument (used by ABS and IF): exactly one value is expected. */
  evalSingleArg(node) {
    const values = this.evalArgValues(node)
    for (const v of values) if (isError(v)) return v
    if (values.length !== 1) return errorValue('#ERR!')
    return values[0]
  }

  evalCall(node) {
    const { name, args } = node
    if (AGGREGATE_FNS.has(name)) {
      if (args.length < 1) return errorValue('#ERR!')
      return this.evalAggregate(name, this.flattenArgs(args))
    }
    if (name === 'ABS') {
      if (args.length !== 1) return errorValue('#ERR!')
      const v = this.evalSingleArg(args[0])
      if (isError(v)) return v
      const c = coerceNumber(v)
      if (isError(c)) return c
      return finiteOrDivZero(Math.abs(c.n))
    }
    if (name === 'IF') {
      if (args.length !== 3) return errorValue('#ERR!')
      return this.evalIf(args)
    }
    return errorValue('#NAME?')
  }

  evalAggregate(name, values) {
    if (name === 'COUNT') {
      for (const v of values) if (isError(v)) return v
      return numberValue(values.filter((v) => v.kind === 'number').length)
    }
    let total = 0
    let best = null
    for (const v of values) {
      const c = coerceNumber(v)
      if (isError(c)) return c
      total += c.n
      best = best === null ? c.n : name === 'MIN' ? Math.min(best, c.n) : Math.max(best, c.n)
    }
    if (name === 'SUM') return finiteOrDivZero(total)
    if (name === 'AVG') return finiteOrDivZero(total / values.length)
    return finiteOrDivZero(best)
  }

  evalIf(args) {
    const cond = this.evalSingleArg(args[0])
    if (isError(cond)) return cond
    let condBool
    if (cond.kind === 'bool') condBool = cond.b
    else if (cond.kind === 'number') condBool = cond.n !== 0
    else return errorValue('#VALUE!')
    return this.evalSingleArg(condBool ? args[1] : args[2])
  }
}
"}

