import { expandRange } from './range.js'

function walk(node, out) {
  switch (node.type) {
    case 'addr': {
      const p = parseAddress(node.word)
      if (p.valid) out.set(p.key, { col: p.col, row: p.row })
      break
    }
    case 'range': {
      const cells = expandRange(node)
      if (cells) for (const c of cells) out.set(c.key, { col: c.col, row: c.row })
      break
    }
    case 'unary':
      walk(node.operand, out)
      break
    case 'bin':
      walk(node.left, out)
      walk(node.right, out)
      break
