{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-ltMwmW/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet } from './parseSheet.js'
import { parseFormula } from './parser.js'
import { Engine } from './engine.js'
import { collectDeps } from './deps.js'
import { formatValue } from './format.js'
import { compareAddresses } from './address.js'
import { SheetError } from './sheetError.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }

  const input = readStdin()

  let cells
  try {
    cells = parseSheet(input)
  } catch (err) {
    if (err instanceof SheetError) fail(err.message)
    throw err
  }

  const keys = [...cells.entries()]
    .map(([key, cell]) => ({ key, col: cell.col, row: cell.row }))
    .sort(compareAddresses)
    .map((c) => c.key)

  const out = []
  if (mode === 'values') {
    const engine = new Engine(cells)
    for (const key of keys) {
      const value = engine.getCellValue(key)
      out.push(`${key}=${formatValue(value)}`)
    }
  } else {
    for (const key of keys) {
      const content = cells.get(key).content
      let deps = []
      if (content.startsWith('=')) {
        try {
          const ast = parseFormula(content.slice(1))
          deps = collectDeps(ast)
        } catch {
          deps = []
        }
      }
      out.push(deps.length ? `${key}: ${deps.join(' ')}` : `${key}:`)
    }
  }

  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

